from typing import Literal, TypedDict
from langgraph.graph import StateGraph, START, END

class State(TypedDict):
    question: str
    route: Literal["sql", "catalog", "rag", "writer"]
    sql_rows: list
    catalog_snapshot: dict
    docs: list
    retries: int
    final_answer: str

def router(state: State):
    q = state["question"].lower()
    if state.get("retries", 0) >= 2:
        return {"route": "writer"}
    if "stock" in q or "order" in q:
        return {"route": "sql"}
    if "price" in q or "catalog" in q:
        return {"route": "catalog"}
    return {"route": "rag"}

def route_edge(state: State):
    return state["route"]

def validator(state: State):
    has_data = bool(state.get("sql_rows") or state.get("catalog_snapshot") or state.get("docs"))
    if has_data:
        return {"route": "writer"}
    return {"retries": state.get("retries", 0) + 1, "route": "sql"}

graph = StateGraph(State)
graph.add_node("router", router)
graph.add_node("sql", sql_node)
graph.add_node("catalog", catalog_node)
graph.add_node("rag", rag_node)
graph.add_node("validator", validator)
graph.add_node("writer", writer_node)

graph.add_edge(START, "router")
graph.add_conditional_edges("router", route_edge, {
    "sql": "sql", "catalog": "catalog", "rag": "rag", "writer": "writer"
})
graph.add_edge("sql", "validator")
graph.add_edge("catalog", "validator")
graph.add_edge("rag", "validator")
graph.add_conditional_edges("validator", route_edge, {
    "sql": "router", "writer": "writer"
})
graph.add_edge("writer", END)
