def estimated_margin(qty, avg_cost, list_price):
    return round((list_price - avg_cost) * qty, 2)

def validate_answer(draft_numbers, tool_payload):
    allowed = set(flatten_numbers(tool_payload))
    allowed.add(estimated_margin(
        tool_payload["qty"], tool_payload["avg_cost"], tool_payload["list_price"]
    ))
    for n in draft_numbers:
        if n not in allowed:
            return False  # retry or refuse
    return True

# Parallel idea in LangGraph: send() to sql, catalog, rag, then join.
# Each tool has a timeout and a fallback: empty result + error flag.
